// Sample workbooks: javascript-excel's conformance corpus (generated by that project,
// MIT, same author). Each sheet is self-describing: column A says what a row tests,
// column B holds the sample, column C says what Excel shows. They are served from
// public/samples and fetched on demand.

export interface Sample {
  id: string;
  title: string;
  covers: string;
  bytes: number;
}

export const SAMPLES: readonly Sample[] = [
  { id: '99-kitchen-sink', title: 'Kitchen sink', covers: 'Every sheet of every corpus file in one workbook', bytes: 42665 },
  { id: '01-values', title: 'Cell values', covers: 'Strings, numbers, booleans, error values, empty styled cells', bytes: 5180 },
  { id: '02-text', title: 'Text and rich text', covers: 'Escapes, line breaks, 32,767-character text, rich-text runs', bytes: 4901 },
  { id: '03-dates', title: 'Dates (1900 system)', covers: 'Dates, times, the 1900 leap-year quirk, the date range', bytes: 4825 },
  { id: '04-dates-1904', title: 'Dates (1904 system)', covers: 'The 1904 date system', bytes: 4465 },
  { id: '05-formulas', title: 'Formulas', covers: 'Cached number/string/boolean/error/date results, array formulas, formulas without a result', bytes: 4667 },
  { id: '06-fonts', title: 'Fonts', covers: 'Every font property and all four colour forms', bytes: 5217 },
  { id: '07-fills', title: 'Fills', covers: 'All 18 pattern types, solid fills, linear and path gradients', bytes: 5301 },
  { id: '08-borders', title: 'Borders', covers: 'All 13 border styles, a colour per side, diagonals', bytes: 5166 },
  { id: '09-alignment', title: 'Alignment', covers: 'Horizontal/vertical alignment, rotation, vertical text, indent, wrap, shrink to fit', bytes: 5482 },
  { id: '10-number-formats', title: 'Number formats', covers: 'Every built-in format id and custom codes', bytes: 7652 },
  { id: '11-number-formats-locale', title: 'Locale number formats', covers: 'Locale-dependent built-in formats (try the locale control)', bytes: 4962 },
  { id: '12-colours', title: 'Colours', covers: 'Theme colours, tints, the indexed palette, automatic colour', bytes: 7997 },
  { id: '13-columns-rows', title: 'Columns and rows', covers: 'Widths, heights, hidden rows and columns, outline levels', bytes: 4611 },
  { id: '14-merges-views', title: 'Merges and views', covers: 'Merges, frozen panes, right-to-left, zoom, gridlines off, tab colours, hidden sheets', bytes: 9260 },
  { id: '15-hyperlinks-names', title: 'Hyperlinks', covers: 'External, mailto and internal links with tooltips; defined names', bytes: 5683 },
  { id: '16-print', title: 'Print setup', covers: 'Page setup, print area and titles (stored; not shown by a viewer)', bytes: 9927 },
  { id: '17-workbook', title: 'Workbook properties', covers: 'Document properties, a non-default font, 31-character sheet names', bytes: 6125 },
  { id: '19-builders', title: 'Dataset builders', covers: 'Header groups as merges, banded rows, frozen header with a filter, totals', bytes: 6670 },
];

export const DEFAULT_SAMPLE = '99-kitchen-sink';

export function findSample(id: string): Sample | undefined {
  return SAMPLES.find((s) => s.id === id);
}

export function sampleUrl(id: string): string {
  return `${import.meta.env.BASE_URL}samples/${id}.xlsx`;
}

export async function fetchSample(id: string, signal?: AbortSignal): Promise<File> {
  const res = await fetch(sampleUrl(id), signal ? { signal } : undefined);
  if (!res.ok) throw new Error(`Could not load the sample ${id} (HTTP ${res.status})`);
  const blob = await res.blob();
  return new File([blob], `${id}.xlsx`, { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
}
